-- Lesson: binomial-parameters
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_66f98563c59d7d', 'binomial-parameters', 'Parameters for a binomial distribution', 'Compute and interpret the mean and standard deviation of a binomial random variable, describe its shape, and decide when a normal approximation is reasonable.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0cc1bf7f465731', 'les_66f98563c59d7d', 1, 'Compute μ = np and σ = √(np(1 − p)) and interpret them in context.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d745fdc47ec996', 'les_66f98563c59d7d', 2, 'Describe how the shape depends on p and n.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_23efaa2c5026db', 'les_66f98563c59d7d', 3, 'Use the Large Counts condition np ≥ 10 and n(1 − p) ≥ 10 for a normal approximation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0cc1bf7f465731', 'les_66f98563c59d7d', 'learn', 1, 'definition', '{"term":"Mean and SD","body":"For $X \\sim B(n, p)$: $\\mu_X = np$ and $\\sigma_X = \\sqrt{np(1 - p)}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d745fdc47ec996', 'les_66f98563c59d7d', 'learn', 2, 'worked_example', '{"title":"40% of a town''s voters support a candidate. Poll 50 at random; $X$ = number of supporters.","steps":[{"latex":"\\mu = 50(0.4) = 20","explanation":"On average, 20 supporters in samples of 50."},{"latex":"\\sigma = \\sqrt{50 \\cdot 0.4 \\cdot 0.6} = \\sqrt{12} \\approx 3.46","explanation":"Counts typically vary by about 3.5 from 20."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_23efaa2c5026db', 'les_66f98563c59d7d', 'learn', 3, 'definition', '{"term":"Shape","body":"Symmetric when $p = 0.5$; skewed right when $p$ is small; skewed left when $p$ is large. As $n$ grows the shape becomes approximately normal; a common check is $np \\ge 10$ and $n(1 - p) \\ge 10$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a238158400612', 'les_66f98563c59d7d', 'learn', 4, 'callout', '{"tone":"tip","title":"Using the normal approximation","body":"With the example above ($np = 20$, $n(1 - p) = 30$), $P(X \\ge 27) \\approx P\\left(Z \\ge \\frac{27 - 20}{3.46}\\right) = P(Z \\ge 2.02) \\approx 0.022$. Technology gives the exact binomial value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_57a04cc767e240', 'les_66f98563c59d7d', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Airlines overbook flights using the binomial mean and SD of no-shows."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0cc1bf7f465731', 'les_66f98563c59d7d', 1, 'practice', 'numeric', 1, '$n = 80$, $p = 0.25$. Find $\mu$.', '{"answer":20}', '[]', '$80(0.25) = 20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d745fdc47ec996', 'les_66f98563c59d7d', 2, 'practice', 'numeric', 2, '$n = 80$, $p = 0.25$. Find $\sigma$ to two decimal places.', '{"answer":3.87,"tolerance":0.01}', '[]', '$\sqrt{80 \cdot 0.25 \cdot 0.75} = \sqrt{15} \approx 3.87$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_23efaa2c5026db', 'les_66f98563c59d7d', 3, 'practice', 'multiple_choice', 2, '$n = 30$, $p = 0.1$. The binomial distribution is…', '{"choices":["approximately normal","skewed right","skewed left","uniform"],"answer":1}', '["$np = 3$."]', 'Small $p$ and $np < 10$: skewed right.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3a238158400612', 'les_66f98563c59d7d', 4, 'review', 'multiple_choice', 3, 'For which setting is a normal approximation reasonable?', '{"choices":["n = 20, p = 0.3","n = 200, p = 0.03","n = 100, p = 0.4","n = 50, p = 0.9"],"answer":2}', '[]', '$np = 40$ and $n(1 - p) = 60$, both at least 10.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_66f98563c59d7d', (SELECT id FROM concepts WHERE slug = 'random-variables'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_66f98563c59d7d', (SELECT id FROM formulas WHERE slug = 'binomial-probability'), 1);

-- Lesson: categorical-association
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2acbf3097f4e5f', 'categorical-association', 'Statistics for two categorical variables', 'Compare conditional relative frequencies and segmented bar charts to decide whether two categorical variables are associated.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_656a53de320d46', 'les_2acbf3097f4e5f', 1, 'Compute conditional relative frequencies from a two-way table.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5096fee19d1af3', 'les_2acbf3097f4e5f', 2, 'Read segmented (stacked) and side-by-side bar charts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bafbe026738029', 'les_2acbf3097f4e5f', 3, 'Decide whether there is an association between two categorical variables.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_656a53de320d46', 'les_2acbf3097f4e5f', 'learn', 1, 'definition', '{"term":"Association","body":"Two categorical variables are associated if knowing the value of one changes the distribution of the other. Compare the conditional distributions: if they''re (nearly) the same, there''s little or no association."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5096fee19d1af3', 'les_2acbf3097f4e5f', 'learn', 2, 'worked_example', '{"title":"Juniors: 72 of 120 prefer online homework. Seniors: 32 of 80.","steps":[{"latex":"\\text{juniors } \\tfrac{72}{120} = 60\\%,\\ \\text{seniors } \\tfrac{32}{80} = 40\\%","explanation":"Conditional relative frequencies."},{"latex":"\\text{the distributions differ}","explanation":"There is an association between grade and preference in these data."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bafbe026738029', 'les_2acbf3097f4e5f', 'learn', 3, 'definition', '{"term":"Segmented bar charts","body":"Each bar represents 100% of one group, divided into segments for the categories of the other variable. If the segments line up across bars, there''s no association."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7fcc8628e5dcc7', 'les_2acbf3097f4e5f', 'learn', 4, 'callout', '{"tone":"warning","title":"Compare percents, not counts","body":"Raw counts mislead when groups differ in size: 72 juniors vs 32 seniors exaggerates the difference."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_466f8ed426c558', 'les_2acbf3097f4e5f', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Public health reports compare vaccination rates across age groups; marketers compare product preferences across regions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_656a53de320d46', 'les_2acbf3097f4e5f', 1, 'practice', 'numeric', 1, 'In a table, 45 of 75 dog owners exercise daily. What percent is that?', '{"answer":60,"unit":"%"}', '[]', '$45/75 = 0.6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5096fee19d1af3', 'les_2acbf3097f4e5f', 2, 'practice', 'multiple_choice', 2, 'Among cat owners, 60% exercise daily; among dog owners, 60% do too. What does this suggest?', '{"choices":["Strong association","No association between pet type and daily exercise in these data","Dogs cause exercise","The sample is biased"],"answer":1}', '[]', 'Identical conditional distributions mean no association.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bafbe026738029', 'les_2acbf3097f4e5f', 3, 'practice', 'multiple_choice', 2, 'In a segmented bar chart, the ''yes'' segments are 30%, 55% and 80% for three age groups. This shows…', '{"choices":["No association","An association between age group and response","Causation","Equal group sizes"],"answer":1}', '[]', 'The conditional distributions differ.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7fcc8628e5dcc7', 'les_2acbf3097f4e5f', 4, 'review', 'multiple_choice', 3, 'Which is the conditional relative frequency of ''smoker'' among men?', '{"choices":["Smoking men ÷ all people","Smoking men ÷ all men","Smoking men ÷ all smokers","All men ÷ all people"],"answer":1}', '[]', 'Condition on men: divide by the men total.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2acbf3097f4e5f', (SELECT id FROM concepts WHERE slug = 'data-types'));

-- Lesson: categorical-data-displays
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_edb87404f63a8e', 'categorical-data-displays', 'Representing a categorical variable with tables and graphs', 'Summarize a categorical variable with frequency and relative frequency tables, display it with bar charts and pie charts, and spot misleading graphs.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6b076e88a71b87', 'les_edb87404f63a8e', 1, 'Build frequency and relative frequency tables.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c6752033bedf77', 'les_edb87404f63a8e', 2, 'Make and read bar charts and pie charts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a88abdb3389221', 'les_edb87404f63a8e', 3, 'Recognize misleading displays, such as truncated axes and pictographs.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b076e88a71b87', 'les_edb87404f63a8e', 'learn', 1, 'definition', '{"term":"Frequency tables","body":"A frequency table gives the count in each category; a relative frequency table gives the proportion or percent. Relative frequencies let you compare groups of different sizes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c6752033bedf77', 'les_edb87404f63a8e', 'learn', 2, 'worked_example', '{"title":"150 students name their preferred transport: bus 60, car 45, walk 30, bike 15","steps":[{"latex":"\\text{bus } \\tfrac{60}{150} = 40\\%,\\ \\text{car } 30\\%,\\ \\text{walk } 20\\%,\\ \\text{bike } 10\\%","explanation":"Relative frequencies sum to 100%."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a88abdb3389221', 'les_edb87404f63a8e', 'learn', 3, 'definition', '{"term":"Bar charts and pie charts","body":"A bar chart uses bar heights for counts or percents; the bars are separated because categories have no order on a number line. A pie chart shows parts of a whole and only works when the categories cover everyone exactly once."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_45ad1e9a06bf80', 'les_edb87404f63a8e', 'learn', 4, 'callout', '{"tone":"warning","title":"Misleading displays","body":"A vertical axis that doesn''t start at 0 exaggerates differences between bars. Pictographs that scale an image''s width and height both make a value look much larger than it is."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c3084826055e84', 'les_edb87404f63a8e', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Election results, market share and survey responses are categorical; news graphics are a common place to practice spotting a truncated axis."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6b076e88a71b87', 'les_edb87404f63a8e', 1, 'practice', 'numeric', 1, '45 of 150 students travel by car. What percent is that?', '{"answer":30,"unit":"%"}', '[]', '$45/150 = 0.30$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c6752033bedf77', 'les_edb87404f63a8e', 2, 'practice', 'multiple_choice', 2, 'Why are the bars in a bar chart separated?', '{"choices":["To save ink","The categories aren''t values on a number scale","To show skew","Pie charts require it"],"answer":1}', '[]', 'Histograms touch because their bins cover a continuous scale; bar chart categories don''t.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a88abdb3389221', 'les_edb87404f63a8e', 3, 'practice', 'multiple_choice', 2, 'A survey lets people choose all the streaming services they use. Can a pie chart display the results?', '{"choices":["Yes","No: a person can be in several categories, so the parts don''t form one whole","Only with percents","Only if there are fewer than 5 services"],"answer":1}', '[]', 'Use a bar chart of percents instead.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_45ad1e9a06bf80', 'les_edb87404f63a8e', 4, 'review', 'multiple_choice', 3, 'A bar chart''s vertical axis runs from 48% to 52%, showing 49% vs 51%. What''s the problem?', '{"choices":["None","It makes a small difference look huge","Bars should touch","Percents can''t be graphed"],"answer":1}', '[]', 'The truncated axis exaggerates a 2-point difference.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_edb87404f63a8e', (SELECT id FROM concepts WHERE slug = 'data-types'));

-- Lesson: central-limit-theorem
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ef587bc527be0d', 'central-limit-theorem', 'The Central Limit Theorem', 'See through simulation that sample means from any population become approximately normal as the sample size grows, and use the CLT to justify normal calculations for x̄.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1663ceaff8891c', 'les_ef587bc527be0d', 1, 'State the Central Limit Theorem.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_27cab46153d228', 'les_ef587bc527be0d', 2, 'Explain how the shape of the population and the sample size affect the shape of the sampling distribution of x̄.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_680222bc31f1aa', 'les_ef587bc527be0d', 3, 'Use the CLT (n ≥ 30 rule of thumb) to justify a normal model.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1663ceaff8891c', 'les_ef587bc527be0d', 'learn', 1, 'definition', '{"term":"Central Limit Theorem","body":"When $n$ is large, the sampling distribution of $\\bar{x}$ is approximately normal, whatever the shape of the population, with mean $\\mu$ and standard deviation $\\frac{\\sigma}{\\sqrt{n}}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_27cab46153d228', 'les_ef587bc527be0d', 'learn', 2, 'definition', '{"term":"How large is large?","body":"If the population is normal, $\\bar{x}$ is normal for any $n$. For moderately skewed populations, $n \\ge 30$ is usually enough. Very strong skew or extreme outliers need larger samples."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_680222bc31f1aa', 'les_ef587bc527be0d', 'learn', 3, 'worked_example', '{"title":"Wait times at a clinic are skewed right with $\\mu = 20$ min and $\\sigma = 15$ min. Find $P(\\bar{x} > 23)$ for 36 random patients.","steps":[{"latex":"n = 36 \\ge 30 \\Rightarrow \\bar{x} \\text{ approximately normal}","explanation":"CLT."},{"latex":"\\sigma_{\\bar{x}} = \\frac{15}{6} = 2.5","explanation":""},{"latex":"z = \\frac{23 - 20}{2.5} = 1.2,\\ P(Z > 1.2) \\approx 0.115","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f7488c0c75353f', 'les_ef587bc527be0d', 'experiment', 4, 'activity', '{"activity":"dice-simulation","title":"Averages of many rolls"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba0cbdf17c29e3', 'les_ef587bc527be0d', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"A single die roll is uniform, not bell-shaped. The average of many rolls clusters tightly around 3.5, the same mechanism the CLT describes."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ab6b6c23ed907', 'les_ef587bc527be0d', 'learn', 6, 'callout', '{"tone":"warning","title":"The CLT is about x̄, not the data","body":"Individual wait times stay skewed no matter how many you collect. It''s the distribution of sample means that becomes normal."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3d029ea517f0db', 'les_ef587bc527be0d', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Quality control charts plot sample means because the CLT makes them approximately normal even when individual measurements aren''t."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1663ceaff8891c', 'les_ef587bc527be0d', 1, 'practice', 'numeric', 2, '$\sigma = 12$, $n = 64$. Find $\sigma_{\bar{x}}$.', '{"answer":1.5,"tolerance":0.001}', '[]', '$\frac{12}{8} = 1.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_27cab46153d228', 'les_ef587bc527be0d', 2, 'practice', 'multiple_choice', 2, 'A population is strongly skewed. As $n$ increases, the sampling distribution of $\bar{x}$ becomes…', '{"choices":["more skewed","closer to normal","uniform","bimodal"],"answer":1}', '[]', 'The CLT.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_680222bc31f1aa', 'les_ef587bc527be0d', 3, 'practice', 'multiple_choice', 2, 'If a population is normal, the sampling distribution of $\bar{x}$ for $n = 5$ is…', '{"choices":["normal","skewed","only approximately normal if n ≥ 30","unknown"],"answer":0}', '[]', 'Means of normal data are exactly normal.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f7488c0c75353f', 'les_ef587bc527be0d', 4, 'review', 'numeric', 3, 'For the clinic example (μ = 20, σ = 15, n = 36), find $P(\bar{x} < 15)$ to three decimal places.', '{"answer":0.023,"tolerance":0.002}', '["$z = \\frac{15 - 20}{2.5}$."]', '$z = -2$, $P(Z < -2) \approx 0.023$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ef587bc527be0d', (SELECT id FROM concepts WHERE slug = 'sampling-distributions'));

-- Lesson: chi-square-goodness-of-fit
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b28abb34736a27', 'chi-square-goodness-of-fit', 'The chi-square goodness of fit test', 'Test whether a categorical variable''s distribution matches a hypothesized distribution, using expected counts, the chi-square statistic and k − 1 degrees of freedom.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a191c931aee706', 'les_b28abb34736a27', 1, 'State hypotheses about a claimed distribution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_de7fe08813f9ba', 'les_b28abb34736a27', 2, 'Compute expected counts and the chi-square statistic.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eae1ec023fd3a9', 'les_b28abb34736a27', 3, 'Find the P-value with k − 1 degrees of freedom and conclude.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a191c931aee706', 'les_b28abb34736a27', 'learn', 1, 'formula', '{"latex":"\\chi^2 = \\sum \\frac{(\\text{observed} - \\text{expected})^2}{\\text{expected}}","title":"Chi-square statistic","note":"Larger values mean observed counts are farther from what H₀ predicts."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de7fe08813f9ba', 'les_b28abb34736a27', 'learn', 2, 'definition', '{"term":"Conditions and df","body":"Random sample; 10% condition; all expected counts at least 5. Degrees of freedom: number of categories minus 1. P-value: area to the right of $\\chi^2$ under the chi-square distribution."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eae1ec023fd3a9', 'les_b28abb34736a27', 'learn', 3, 'worked_example', '{"title":"Is a die fair? 60 rolls give counts 8, 9, 12, 11, 6, 14 for faces 1 to 6.","steps":[{"latex":"H_0: \\text{each face has probability } \\tfrac{1}{6}","explanation":"Expected count 10 each (all ≥ 5)."},{"latex":"\\chi^2 = \\tfrac{4 + 1 + 4 + 1 + 16 + 16}{10} = 4.2","explanation":""},{"latex":"df = 5,\\ \\text{P-value} \\approx 0.52","explanation":""},{"latex":"\\text{fail to reject } H_0","explanation":"No convincing evidence the die is unfair."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1b866e018c185a', 'les_b28abb34736a27', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Geneticists test whether offspring match Mendel''s predicted ratios, and auditors test whether digits follow an expected pattern."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a191c931aee706', 'les_b28abb34736a27', 1, 'practice', 'numeric', 1, '200 trials, hypothesized proportion 0.25 for one category. Find its expected count.', '{"answer":50}', '[]', '$200(0.25) = 50$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_de7fe08813f9ba', 'les_b28abb34736a27', 2, 'practice', 'numeric', 2, 'Observed 30, expected 25. Find this category''s contribution to $\chi^2$.', '{"answer":1}', '[]', '$\frac{25}{25} = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eae1ec023fd3a9', 'les_b28abb34736a27', 3, 'practice', 'numeric', 2, 'A test has 4 categories. How many degrees of freedom?', '{"answer":3}', '[]', '$4 - 1 = 3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1b866e018c185a', 'les_b28abb34736a27', 4, 'review', 'multiple_choice', 3, '$\chi^2 = 10.5$ with $df = 3$. Using the critical value 7.81 at $\alpha = 0.05$, you…', '{"choices":["reject H₀","fail to reject H₀","need more categories","accept H₀"],"answer":0}', '[]', '$10.5 > 7.81$ (P-value ≈ 0.015).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5b4e7f0ebe49d3', 'subj_math', 'chi-square', 'Chi-square tests', 'Tests comparing observed counts with expected counts for categorical data.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b28abb34736a27', (SELECT id FROM concepts WHERE slug = 'chi-square'));

-- Lesson: chi-square-homogeneity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_884b0fd3dc6070', 'chi-square-homogeneity', 'The chi-square test for homogeneity', 'Test whether the distribution of a categorical variable is the same in several populations or treatment groups, using separate random samples or random assignment.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_441e70d5a8ff64', 'les_884b0fd3dc6070', 1, 'Recognize homogeneity settings: several samples or groups, one categorical variable.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_35ca7710b02e8b', 'les_884b0fd3dc6070', 2, 'Carry out the test with expected counts and (r − 1)(c − 1) df.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eef36405ab2bf1', 'les_884b0fd3dc6070', 3, 'Interpret results, including which cells contribute most.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_441e70d5a8ff64', 'les_884b0fd3dc6070', 'learn', 1, 'definition', '{"term":"Hypotheses","body":"$H_0$: the distribution of the variable is the same in all populations (or treatments). $H_a$: the distributions are not all the same."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_35ca7710b02e8b', 'les_884b0fd3dc6070', 'learn', 2, 'worked_example', '{"title":"Randomized experiment: 60 of 100 improved on a treatment, 40 of 100 on a placebo.","steps":[{"latex":"\\text{expected: 50 improve, 50 don''t, in each group}","explanation":"All ≥ 5."},{"latex":"\\chi^2 = 4 \\cdot \\frac{10^2}{50} = 8","explanation":"Each cell contributes 2."},{"latex":"df = 1,\\ \\text{P-value} \\approx 0.005","explanation":""},{"latex":"\\text{reject } H_0","explanation":"Convincing evidence the improvement distribution differs between treatment and placebo; with random assignment, the treatment causes the difference."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eef36405ab2bf1', 'les_884b0fd3dc6070', 'learn', 3, 'callout', '{"tone":"tip","title":"Follow-up","body":"Look at the components $\\frac{(O - E)^2}{E}$: the largest ones show where the distributions differ most."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_54b979bd036b07', 'les_884b0fd3dc6070', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Researchers compare the distribution of political party, product preference or side effects across several groups."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_441e70d5a8ff64', 'les_884b0fd3dc6070', 1, 'practice', 'multiple_choice', 1, 'Random samples are taken from three high schools and students report their favorite subject. Which test?', '{"choices":["Goodness of fit","Homogeneity","Independence","Two-sample t"],"answer":1}', '[]', 'Several samples, one categorical variable.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_35ca7710b02e8b', 'les_884b0fd3dc6070', 2, 'practice', 'numeric', 2, 'Observed 45, expected 36. Find the component of $\chi^2$.', '{"answer":2.25,"tolerance":0.001}', '[]', '$\frac{81}{36} = 2.25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eef36405ab2bf1', 'les_884b0fd3dc6070', 3, 'practice', 'numeric', 2, 'A homogeneity test compares 4 groups on a 3-category variable. Find df.', '{"answer":6}', '[]', '$(3 - 1)(4 - 1) = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_54b979bd036b07', 'les_884b0fd3dc6070', 4, 'review', 'multiple_choice', 3, 'A homogeneity test gives P-value 0.30. Conclusion?', '{"choices":["The distributions are identical","No convincing evidence the distributions differ","Reject H₀","The groups are biased"],"answer":1}', '[]', 'Large P-value: fail to reject.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5b4e7f0ebe49d3', 'subj_math', 'chi-square', 'Chi-square tests', 'Tests comparing observed counts with expected counts for categorical data.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_884b0fd3dc6070', (SELECT id FROM concepts WHERE slug = 'chi-square'));

-- Lesson: chi-square-independence
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_00971efbb12a86', 'chi-square-independence', 'The chi-square test for independence', 'Test whether two categorical variables are associated in a population, using a single random sample classified by both variables.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_97b8896792a86a', 'les_00971efbb12a86', 1, 'Distinguish independence (one sample, two variables) from homogeneity (several samples, one variable).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ba31fb2f2865d8', 'les_00971efbb12a86', 2, 'Carry out the test and interpret the P-value.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5c00af326e0fac', 'les_00971efbb12a86', 3, 'State conclusions about association, not causation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97b8896792a86a', 'les_00971efbb12a86', 'learn', 1, 'definition', '{"term":"Hypotheses","body":"$H_0$: there is no association between the two variables in the population (they''re independent). $H_a$: there is an association."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba31fb2f2865d8', 'les_00971efbb12a86', 'learn', 2, 'worked_example', '{"title":"200 randomly chosen students: plays a sport and grade B or above 50; sport and below B 30; no sport and B or above 50; no sport and below B 70.","steps":[{"latex":"\\text{totals: sport 80, no sport 120; B+ 100, below 100}","explanation":""},{"latex":"\\text{expected: } 40, 40, 60, 60","explanation":""},{"latex":"\\chi^2 = \\tfrac{100}{40} + \\tfrac{100}{40} + \\tfrac{100}{60} + \\tfrac{100}{60} \\approx 8.33","explanation":""},{"latex":"df = 1,\\ \\text{P-value} \\approx 0.004","explanation":""},{"latex":"\\text{reject } H_0","explanation":"Convincing evidence of an association between playing a sport and grades among the school''s students; no causal claim."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5c00af326e0fac', 'les_00971efbb12a86', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Survey researchers test whether opinions are associated with age group, region or education level."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97b8896792a86a', 'les_00971efbb12a86', 1, 'practice', 'multiple_choice', 1, 'One random sample of adults is classified by smoking status and exercise level. Which test?', '{"choices":["Homogeneity","Independence","Goodness of fit","Paired t"],"answer":1}', '[]', 'One sample, two categorical variables.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ba31fb2f2865d8', 'les_00971efbb12a86', 2, 'practice', 'multiple_choice', 2, 'What does the null hypothesis say?', '{"choices":["The variables are associated","There is no association between the variables in the population","The sample is random","The means are equal"],"answer":1}', '[]', 'Independence.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5c00af326e0fac', 'les_00971efbb12a86', 3, 'practice', 'numeric', 2, 'A 2 × 3 independence test: how many degrees of freedom?', '{"answer":2}', '[]', '$(2 - 1)(3 - 1) = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c6f3fd78afe337', 'les_00971efbb12a86', 4, 'review', 'multiple_choice', 3, 'An independence test from a random sample finds a significant association. You can conclude…', '{"choices":["One variable causes the other","The variables are associated in the population","Nothing","The sample is biased"],"answer":1}', '[]', 'Random sampling supports generalization, not causation.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5b4e7f0ebe49d3', 'subj_math', 'chi-square', 'Chi-square tests', 'Tests comparing observed counts with expected counts for categorical data.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_00971efbb12a86', (SELECT id FROM concepts WHERE slug = 'chi-square'));

-- Lesson: departures-from-linearity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_61197d4372a803', 'departures-from-linearity', 'Analyzing departures from linearity', 'Identify outliers, high-leverage points and influential points in regression, and transform data with logarithms or powers to straighten curved relationships.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b197cd596f1e90', 'les_61197d4372a803', 1, 'Distinguish outliers, high-leverage points and influential points.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4c31f8b9891c81', 'les_61197d4372a803', 2, 'Describe how an influential point changes the slope, intercept and r.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_af497396f3d90a', 'les_61197d4372a803', 3, 'Use log and power transformations to linearize data, then back-transform predictions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b197cd596f1e90', 'les_61197d4372a803', 'learn', 1, 'definition', '{"term":"Unusual points","body":"An outlier in regression has a large residual. A high-leverage point has an $x$-value far from $\\bar{x}$. A point is influential if removing it substantially changes the slope, intercept or correlation; high-leverage points are often influential."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c31f8b9891c81', 'les_61197d4372a803', 'learn', 2, 'worked_example', '{"title":"10 points with $r = 0.2$; adding one point far to the right and high makes $r = 0.8$","steps":[{"latex":"\\text{the new point is high-leverage and influential}","explanation":"One point manufactured most of the correlation."},{"latex":"\\text{report results with and without it}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af497396f3d90a', 'les_61197d4372a803', 'learn', 3, 'definition', '{"term":"Transformations","body":"If $y$ grows exponentially in $x$, then $\\ln y$ is linear in $x$. If $y$ follows a power model $y = ax^p$, then $\\ln y$ is linear in $\\ln x$. Fit a line to the transformed data, check its residual plot, then undo the transformation to predict."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffa41ff4aa6519', 'les_61197d4372a803', 'learn', 4, 'worked_example', '{"title":"A fitted model is $\\widehat{\\ln y} = 1.2 + 0.3x$. Predict $y$ at $x = 4$.","steps":[{"latex":"\\widehat{\\ln y} = 1.2 + 1.2 = 2.4","explanation":""},{"latex":"\\hat{y} = e^{2.4} \\approx 11.0","explanation":"Back-transform."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_13cb4481e43202', 'les_61197d4372a803', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Biologists fit power models (metabolism vs body mass) on log-log scales; epidemiologists fit early outbreak data on a log scale."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b197cd596f1e90', 'les_61197d4372a803', 1, 'practice', 'multiple_choice', 1, 'A point with an unusually large residual is…', '{"choices":["high-leverage","an outlier","always influential","the mean"],"answer":1}', '[]', 'Outliers in regression are far from the line vertically.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c31f8b9891c81', 'les_61197d4372a803', 2, 'practice', 'multiple_choice', 2, 'Which point is most likely to be influential?', '{"choices":["One near the middle of the x-values, on the line","One with an extreme x-value that doesn''t follow the pattern","One with a small residual near x̄","The point (x̄, ȳ)"],"answer":1}', '[]', 'High leverage plus not following the pattern pulls the line.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af497396f3d90a', 'les_61197d4372a803', 3, 'practice', 'numeric', 2, 'A model is $\widehat{\ln y} = 0.5 + 0.2x$. Predict $y$ at $x = 5$, to two decimal places.', '{"answer":4.48,"tolerance":0.01}', '[]', '$\widehat{\ln y} = 1.5$, so $\hat{y} = e^{1.5} \approx 4.48$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ffa41ff4aa6519', 'les_61197d4372a803', 4, 'review', 'multiple_choice', 3, 'A scatterplot of $\ln y$ against $x$ is linear. Which model fits $y$ and $x$?', '{"choices":["Linear","Exponential","Power","Logarithmic"],"answer":1}', '[]', '$\ln y = a + bx$ means $y = e^a(e^b)^x$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_61197d4372a803', (SELECT id FROM concepts WHERE slug = 'regression'));

-- Lesson: expected-counts-two-way
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0bdaefd6ab6367', 'expected-counts-two-way', 'Expected counts in two-way tables', 'Compute the counts a two-way table would have if there were no association, (row total × column total) ÷ table total, and the degrees of freedom (r − 1)(c − 1).', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2fa0e02be0cb18', 'les_0bdaefd6ab6367', 1, 'Compute expected counts under the null hypothesis of no association.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_76214b30ce448d', 'les_0bdaefd6ab6367', 2, 'Explain why the formula works.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_49b8cb7f04c168', 'les_0bdaefd6ab6367', 3, 'Find degrees of freedom for an r × c table.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2fa0e02be0cb18', 'les_0bdaefd6ab6367', 'learn', 1, 'definition', '{"term":"Expected count","body":"$\\text{expected} = \\frac{\\text{row total} \\times \\text{column total}}{\\text{table total}}$. It''s what we''d see if every row had the same distribution across the columns as the table overall."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_76214b30ce448d', 'les_0bdaefd6ab6367', 'learn', 2, 'worked_example', '{"title":"100 men and 100 women answer yes or no; 120 say yes in total.","steps":[{"latex":"\\text{expected men--yes} = \\frac{100 \\cdot 120}{200} = 60","explanation":"60% say yes overall, so 60% of the 100 men."},{"latex":"\\text{men--no} = 40,\\ \\text{women--yes} = 60,\\ \\text{women--no} = 40","explanation":"The rest follow from the totals."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_49b8cb7f04c168', 'les_0bdaefd6ab6367', 'learn', 3, 'definition', '{"term":"Degrees of freedom","body":"$df = (r - 1)(c - 1)$ for $r$ rows and $c$ columns: once those cells are filled in, the totals force the rest."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0f9b28094115c4', 'les_0bdaefd6ab6367', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Expected counts are the benchmark for every chi-square test of homogeneity or independence."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2fa0e02be0cb18', 'les_0bdaefd6ab6367', 1, 'practice', 'numeric', 1, 'Row total 50, column total 80, table total 200. Find the expected count.', '{"answer":20}', '[]', '$\frac{50 \cdot 80}{200} = 20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_76214b30ce448d', 'les_0bdaefd6ab6367', 2, 'practice', 'numeric', 2, 'How many degrees of freedom does a 3 × 4 table have?', '{"answer":6}', '[]', '$2 \cdot 3 = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_49b8cb7f04c168', 'les_0bdaefd6ab6367', 3, 'practice', 'multiple_choice', 2, 'Expected counts represent…', '{"choices":["the observed data","counts if there were no association","counts in a random sample","the largest counts"],"answer":1}', '[]', 'They are computed assuming $H_0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0f9b28094115c4', 'les_0bdaefd6ab6367', 4, 'review', 'numeric', 3, 'A 2 × 2 table has total 400; row 1 total 150; column 1 total 240. Find the expected count in row 2, column 1.', '{"answer":150}', '["Row 2 total is 250."]', '$\frac{250 \cdot 240}{400} = 150$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_5b4e7f0ebe49d3', 'subj_math', 'chi-square', 'Chi-square tests', 'Tests comparing observed counts with expected counts for categorical data.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0bdaefd6ab6367', (SELECT id FROM concepts WHERE slug = 'chi-square'));

-- Lesson: experimental-design-selection
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7354c81e4099df', 'experimental-design-selection', 'Selecting an experimental design', 'Choose between completely randomized, randomized block and matched pairs designs, and describe how to carry out each with random assignment.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5b957b129e5a91', 'les_7354c81e4099df', 1, 'Describe a completely randomized design and how to randomize.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_97257cab83f9e4', 'les_7354c81e4099df', 2, 'Choose a blocking variable and describe a randomized block design.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_64bd1c14469df6', 'les_7354c81e4099df', 3, 'Explain when a matched pairs design is most effective.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b957b129e5a91', 'les_7354c81e4099df', 'learn', 1, 'definition', '{"term":"Completely randomized design","body":"All units are assigned to treatments completely at random, for example by drawing numbered slips or using a random number generator to pick half the units for treatment A."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_97257cab83f9e4', 'les_7354c81e4099df', 'learn', 2, 'definition', '{"term":"Randomized block design","body":"First form blocks of units that are similar on a variable expected to affect the response; then randomly assign treatments within each block. Blocking reduces variability, making treatment differences easier to detect."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64bd1c14469df6', 'les_7354c81e4099df', 'learn', 3, 'definition', '{"term":"Matched pairs","body":"Pairs of very similar units (or each unit used twice, in random order) get the two treatments. Analyze the differences within each pair."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cef4992749b1c4', 'les_7354c81e4099df', 'learn', 4, 'worked_example', '{"title":"Comparing two tire brands for wear","steps":[{"latex":"\\text{completely randomized: assign brands to 20 cars at random}","explanation":"Car-to-car differences in driving add noise."},{"latex":"\\text{matched pairs: put one of each brand on each car, sides chosen at random}","explanation":"Each car''s driving affects both brands equally."},{"latex":"\\text{matched pairs is better here}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f587c61538e865', 'les_7354c81e4099df', 'learn', 5, 'callout', '{"tone":"tip","title":"Choosing a blocking variable","body":"Block on a variable that you expect to affect the response (age, soil type, initial fitness), not one you''re studying."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be53194936fe3e', 'les_7354c81e4099df', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Agricultural field trials block by field location; taste tests use matched pairs, with each taster trying both products in random order."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b957b129e5a91', 'les_7354c81e4099df', 1, 'practice', 'multiple_choice', 1, 'Why block in an experiment?', '{"choices":["To avoid randomization","To reduce the variability due to a known source","To create a placebo","To increase bias"],"answer":1}', '[]', 'Comparisons happen within similar units.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_97257cab83f9e4', 'les_7354c81e4099df', 2, 'practice', 'multiple_choice', 2, 'A study of a reading program suspects that prior reading level matters. A good design blocks on…', '{"choices":["The program","Prior reading level","Student ID","Test date"],"answer":1}', '[]', 'Block on the variable expected to affect the response.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_64bd1c14469df6', 'les_7354c81e4099df', 3, 'practice', 'multiple_choice', 2, 'Each subject tries two keyboards in random order. This is…', '{"choices":["Completely randomized","Matched pairs","Observational","Cluster sampling"],"answer":1}', '[]', 'Each subject receives both treatments.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cef4992749b1c4', 'les_7354c81e4099df', 4, 'review', 'multiple_choice', 3, 'In a block design with blocks for men and women, how is randomization done?', '{"choices":["Once, across everyone","Separately within each block","Not at all","Only for women"],"answer":1}', '[]', 'Random assignment happens within each block.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7354c81e4099df', (SELECT id FROM concepts WHERE slug = 'study-design'));

-- Lesson: inference-and-experiments
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d340da4daaabfd', 'inference-and-experiments', 'Inference and experiments', 'Use simulation of random reassignment to judge whether a difference in an experiment is statistically significant, and state the scope of inference from how the data were collected.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6b0353bde32f7f', 'les_d340da4daaabfd', 1, 'Explain statistical significance as ''unlikely to happen by chance alone''.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_14246746aad448', 'les_d340da4daaabfd', 2, 'Use a randomization simulation to judge an observed difference.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_11ad18ae350c3d', 'les_d340da4daaabfd', 3, 'State the scope of inference: generalization from random sampling, causation from random assignment.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b0353bde32f7f', 'les_d340da4daaabfd', 'learn', 1, 'definition', '{"term":"Statistically significant","body":"An observed effect is statistically significant if it''s so large that it would rarely occur by chance alone, if the treatments really had no effect."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_14246746aad448', 'les_d340da4daaabfd', 'learn', 2, 'worked_example', '{"title":"In an experiment, 18 of 30 subjects improved with a new treatment vs 9 of 30 with a placebo: a difference of 0.30.","steps":[{"latex":"\\text{assume no effect: the 27 improvers would improve either way}","explanation":""},{"latex":"\\text{simulate: reshuffle the 60 outcomes into two groups of 30, many times}","explanation":"Record the difference each time."},{"latex":"\\text{if differences} \\ge 0.30 \\text{ occur in only about 1\\% of reshuffles}","explanation":"The observed result is unlikely by chance alone: statistically significant."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_11ad18ae350c3d', 'les_d340da4daaabfd', 'learn', 3, 'definition', '{"term":"Scope of inference","body":"Random sampling allows generalizing to the population sampled. Random assignment to treatments allows cause-and-effect conclusions. Most experiments use volunteers: causation is supported, but only for subjects like these."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d9829a3f67faaf', 'les_d340da4daaabfd', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Randomization tests are used in clinical research and A/B testing because they rely only on the random assignment actually performed."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6b0353bde32f7f', 'les_d340da4daaabfd', 1, 'practice', 'multiple_choice', 1, 'A result is statistically significant when it is…', '{"choices":["large in practical terms","unlikely to occur by chance alone if there is no real effect","based on a big sample","from an observational study"],"answer":1}', '[]', 'Significance is about chance, not importance.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_14246746aad448', 'les_d340da4daaabfd', 2, 'practice', 'multiple_choice', 2, 'In 1,000 reshuffles, a difference as large as the observed one appeared 230 times. The result is…', '{"choices":["Statistically significant","Not statistically significant: chance alone often produces it","Proof of no effect","Biased"],"answer":1}', '[]', '23% of the time is not rare.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_11ad18ae350c3d', 'les_d340da4daaabfd', 3, 'practice', 'multiple_choice', 2, 'Volunteers are randomly assigned to two diets. What can be concluded from a significant difference?', '{"choices":["Diet causes the difference for people like these volunteers","The result applies to all adults","Only association","Nothing"],"answer":0}', '[]', 'Random assignment supports causation; no random sample limits generalization.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d9829a3f67faaf', 'les_d340da4daaabfd', 4, 'review', 'multiple_choice', 3, 'A random sample of adults is surveyed about exercise and mood. A significant association can be…', '{"choices":["generalized to the population, but not shown to be causal","shown to be causal, but not generalized","both","neither"],"answer":0}', '[]', 'Random sampling without random assignment.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d340da4daaabfd', (SELECT id FROM concepts WHERE slug = 'study-design'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d340da4daaabfd', (SELECT id FROM concepts WHERE slug = 'significance-tests'));

-- Lesson: justifying-claims-intervals
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_096c7cda80f8ae', 'justifying-claims-intervals', 'Justifying a claim based on a confidence interval', 'Use a confidence interval to evaluate a claim about a parameter, explain how confidence level and sample size affect width, and choose a sample size for a desired margin of error.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_336b17af77445e', 'les_096c7cda80f8ae', 1, 'Decide whether a claimed value is plausible using an interval.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f0b2bc3974ae5b', 'les_096c7cda80f8ae', 2, 'Explain the effects of confidence level and sample size on the margin of error.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a0a2c94ac2a535', 'les_096c7cda80f8ae', 3, 'Find the sample size needed for a target margin of error.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_336b17af77445e', 'les_096c7cda80f8ae', 'learn', 1, 'definition', '{"term":"Plausible values","body":"Values inside a confidence interval are plausible for the parameter; values outside are not. An interval entirely above 0.5 gives convincing evidence of a majority."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0b2bc3974ae5b', 'les_096c7cda80f8ae', 'learn', 2, 'worked_example', '{"title":"A 95% interval for the proportion supporting a measure is (0.48, 0.56). Is there convincing evidence of majority support?","steps":[{"latex":"0.5 \\text{ is inside the interval}","explanation":""},{"latex":"\\text{no convincing evidence of a majority}","explanation":"But values above 0.5 are also plausible: the data don''t rule majority support out either."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a0a2c94ac2a535', 'les_096c7cda80f8ae', 'learn', 3, 'definition', '{"term":"Choosing n","body":"For a margin of error $ME$: $n \\ge \\left(\\frac{z^*}{ME}\\right)^2 p^*(1 - p^*)$. Use $p^* = 0.5$ when you have no prior estimate; it gives the largest (safest) $n$. Always round up."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fb6d495a0b5b0f', 'les_096c7cda80f8ae', 'learn', 4, 'worked_example', '{"title":"What sample size gives a 95% margin of error of 3 percentage points?","steps":[{"latex":"n \\ge \\left(\\tfrac{1.96}{0.03}\\right)^2(0.25) \\approx 1067.1","explanation":""},{"latex":"n = 1068","explanation":"Round up."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_43504058772793', 'les_096c7cda80f8ae', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"National polls of about 1,000 people report margins near ±3 points, exactly this calculation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_336b17af77445e', 'les_096c7cda80f8ae', 1, 'practice', 'multiple_choice', 1, 'A 95% interval for $p$ is (0.31, 0.39). Is $p = 0.4$ plausible?', '{"choices":["Yes","No","Only at 90%","Can''t tell"],"answer":1}', '[]', '0.4 is outside the interval.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0b2bc3974ae5b', 'les_096c7cda80f8ae', 2, 'practice', 'numeric', 2, 'What sample size gives a 95% margin of error of 0.05 with $p^* = 0.5$?', '{"answer":385}', '["$\\left(\\frac{1.96}{0.05}\\right)^2(0.25) = 384.16$."]', 'Round up to 385.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a0a2c94ac2a535', 'les_096c7cda80f8ae', 3, 'practice', 'multiple_choice', 2, 'Holding the confidence level fixed, quadrupling $n$ makes the margin of error…', '{"choices":["4 times larger","half as large","a quarter as large","unchanged"],"answer":1}', '[]', 'ME is proportional to $1/\sqrt{n}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fb6d495a0b5b0f', 'les_096c7cda80f8ae', 4, 'review', 'multiple_choice', 3, 'A company claims at most 5% of its products are defective. A 99% interval for the defect rate is (0.061, 0.094). What''s the conclusion?', '{"choices":["The claim is supported","Convincing evidence the defect rate exceeds 5%","No evidence either way","The interval is invalid"],"answer":1}', '[]', 'The whole interval lies above 0.05.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_096c7cda80f8ae', (SELECT id FROM concepts WHERE slug = 'confidence-intervals'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_096c7cda80f8ae', (SELECT id FROM formulas WHERE slug = 'proportion-interval'), 1);

-- Lesson: point-estimates-bias
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cdb624f9edfe27', 'point-estimates-bias', 'Biased and unbiased point estimates', 'Judge statistics as estimators by their bias (whether the sampling distribution is centered on the parameter) and their variability, and see how sample size affects each.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_418796c06f2289', 'les_cdb624f9edfe27', 1, 'Define an unbiased estimator.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_658c4a15069563', 'les_cdb624f9edfe27', 2, 'Compare estimators by bias and variability using simulated sampling distributions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d09d32a9863353', 'les_cdb624f9edfe27', 3, 'Explain that larger samples reduce variability but not bias.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_418796c06f2289', 'les_cdb624f9edfe27', 'learn', 1, 'definition', '{"term":"Unbiased estimator","body":"A statistic is an unbiased estimator of a parameter if the mean of its sampling distribution equals the parameter. $\\hat{p}$ is unbiased for $p$, $\\bar{x}$ for $\\mu$, and $s^2$ (dividing by $n - 1$) for $\\sigma^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_658c4a15069563', 'les_cdb624f9edfe27', 'learn', 2, 'definition', '{"term":"Variability","body":"The spread of the sampling distribution. Larger random samples give less variability, which is why bigger samples give more precise estimates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d09d32a9863353', 'les_cdb624f9edfe27', 'learn', 3, 'worked_example', '{"title":"Simulated sampling distributions of two estimators of a population maximum, 100","steps":[{"latex":"\\text{sample maximum: centered near 96}","explanation":"Biased low: a sample can''t exceed the population maximum and rarely contains it."},{"latex":"\\text{an adjusted estimator: centered at 100 but more spread out}","explanation":"Unbiased but more variable."},{"latex":"\\text{best: low bias and low variability}","explanation":"Sometimes a small bias is worth a big reduction in variability."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bc81ea60bf6b37', 'les_cdb624f9edfe27', 'learn', 4, 'callout', '{"tone":"tip","title":"The target picture","body":"Bias is like a rifle sighted off-center: shots cluster in the wrong place. Variability is like a shaky hand: shots scatter. You want both small."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b3a843976ffdfa', 'les_cdb624f9edfe27', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Statisticians compare estimation methods by simulating thousands of samples and measuring each method''s bias and variability before using it on real data."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_418796c06f2289', 'les_cdb624f9edfe27', 1, 'practice', 'multiple_choice', 1, 'An estimator''s sampling distribution is centered exactly at the parameter. It is…', '{"choices":["biased","unbiased","always precise","a parameter"],"answer":1}', '[]', 'That''s the definition.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_658c4a15069563', 'les_cdb624f9edfe27', 2, 'practice', 'multiple_choice', 2, 'Increasing the sample size…', '{"choices":["reduces bias","reduces variability","reduces both always","changes neither"],"answer":1}', '[]', 'Variability shrinks with $n$; bias from the method doesn''t.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d09d32a9863353', 'les_cdb624f9edfe27', 3, 'practice', 'multiple_choice', 2, 'Why is the sample range a biased estimator of the population range?', '{"choices":["It''s usually too large","It''s usually too small, since a sample rarely includes the extremes","It''s unbiased","It depends on units"],"answer":1}', '[]', 'The sample can''t spread wider than the population.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bc81ea60bf6b37', 'les_cdb624f9edfe27', 4, 'review', 'multiple_choice', 3, 'Estimator A: centered on the parameter, SD 5. Estimator B: centered 0.2 above, SD 1. Which is likely to give estimates closer to the truth?', '{"choices":["A","B","Same","Can''t tell"],"answer":1}', '[]', 'B''s tiny bias is outweighed by its much lower variability.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cdb624f9edfe27', (SELECT id FROM concepts WHERE slug = 'sampling-distributions'));

-- Lesson: random-variable-distributions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_03c79b1ebef568', 'random-variable-distributions', 'Introduction to random variables and probability distributions', 'Describe discrete and continuous random variables with probability distributions, compute probabilities of events like X ≤ k, and read probabilities as areas under density curves.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e1c643511b859a', 'les_03c79b1ebef568', 1, 'Write and check a discrete probability distribution.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_008612a2b9f6e2', 'les_03c79b1ebef568', 2, 'Compute probabilities of events such as P(X ≥ 2) and cumulative probabilities.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0357d81d4a9943', 'les_03c79b1ebef568', 3, 'Interpret probabilities for continuous random variables as areas.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e1c643511b859a', 'les_03c79b1ebef568', 'learn', 1, 'definition', '{"term":"Discrete probability distribution","body":"A list of the possible values of $X$ and their probabilities. Each probability is between 0 and 1 and they sum to 1. Display it with a probability histogram."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_008612a2b9f6e2', 'les_03c79b1ebef568', 'learn', 2, 'worked_example', '{"title":"$X$ = number of cars in a randomly chosen household: $P(0) = 0.10$, $P(1) = 0.35$, $P(2) = 0.40$, $P(3) = 0.15$","steps":[{"latex":"0.10 + 0.35 + 0.40 + 0.15 = 1","explanation":"Valid."},{"latex":"P(X \\ge 2) = 0.40 + 0.15 = 0.55","explanation":""},{"latex":"P(X \\le 1) = 0.45","explanation":"Cumulative probability (the complement)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0357d81d4a9943', 'les_03c79b1ebef568', 'learn', 3, 'definition', '{"term":"Continuous random variables","body":"A continuous random variable takes values in an interval. Probabilities are areas under a density curve (total area 1), so $P(X = a) = 0$ for any single value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_87f134a269e47c', 'les_03c79b1ebef568', 'learn', 4, 'worked_example', '{"title":"$X$ is uniform on $[0, 10]$. Find $P(2 < X < 5)$.","steps":[{"latex":"\\text{height} = \\tfrac{1}{10},\\ \\text{width} = 3","explanation":""},{"latex":"P = 0.3","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dab024fdfba2e1', 'les_03c79b1ebef568', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Insurers model the number of claims per policy (discrete) and the size of a claim (continuous) with probability distributions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e1c643511b859a', 'les_03c79b1ebef568', 1, 'practice', 'numeric', 1, 'Using the car distribution, find $P(X = 1 \text{ or } X = 2)$.', '{"answer":0.75,"tolerance":0.001}', '[]', '$0.35 + 0.40 = 0.75$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_008612a2b9f6e2', 'les_03c79b1ebef568', 2, 'practice', 'numeric', 2, 'A distribution has $P(0) = 0.2$, $P(1) = 0.5$ and $P(2) = k$. Find $k$.', '{"answer":0.3,"tolerance":0.001}', '[]', '$1 - 0.7 = 0.3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0357d81d4a9943', 'les_03c79b1ebef568', 3, 'practice', 'numeric', 2, '$X$ is uniform on $[0, 4]$. Find $P(X > 3)$.', '{"answer":0.25,"tolerance":0.001}', '[]', '$\frac{1}{4} \cdot 1 = 0.25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_87f134a269e47c', 'les_03c79b1ebef568', 4, 'review', 'multiple_choice', 3, 'For a continuous random variable, $P(X \le 5)$ and $P(X < 5)$ are…', '{"choices":["different by P(X = 5) > 0","equal","always 0.5","undefined"],"answer":1}', '[]', '$P(X = 5) = 0$ for a continuous variable.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_03c79b1ebef568', (SELECT id FROM concepts WHERE slug = 'random-variables'));

-- Lesson: sampling-bias
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_558a3358283bc6', 'sampling-bias', 'Potential problems with sampling', 'Recognize undercoverage, nonresponse, response bias and question-wording effects, and explain how each can bias the results of a survey even when the sample is random.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e5ecb7ecfc93a', 'les_558a3358283bc6', 1, 'Identify undercoverage, nonresponse bias, response bias and wording bias.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aac370708567ff', 'les_558a3358283bc6', 2, 'Predict the direction of the bias in context.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cca95f3323693b', 'les_558a3358283bc6', 3, 'Distinguish bias from ordinary sampling variability.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e5ecb7ecfc93a', 'les_558a3358283bc6', 'learn', 1, 'definition', '{"term":"Undercoverage","body":"Some members of the population are less likely to be chosen or can''t be chosen at all, for example a phone survey that misses people without phones."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aac370708567ff', 'les_558a3358283bc6', 'learn', 2, 'definition', '{"term":"Nonresponse","body":"Selected individuals can''t be contacted or refuse to answer, and nonresponders may differ from responders."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cca95f3323693b', 'les_558a3358283bc6', 'learn', 3, 'definition', '{"term":"Response bias","body":"Answers are systematically inaccurate: people misremember, or give socially desirable answers, especially to a live interviewer."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9cef302ed7d678', 'les_558a3358283bc6', 'learn', 4, 'definition', '{"term":"Wording","body":"Leading or confusing questions push answers in one direction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0fcbf20b8511be', 'les_558a3358283bc6', 'learn', 5, 'worked_example', '{"title":"\"Don''t you agree that the city should fix its dangerous, crumbling roads?\"","steps":[{"latex":"\\text{wording bias}","explanation":"''Don''t you agree'' and ''dangerous, crumbling'' push toward yes."},{"latex":"\\text{estimate of support is likely too high}","explanation":"State the direction of the bias."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_830e0a84f56e5c', 'les_558a3358283bc6', 'learn', 6, 'callout', '{"tone":"warning","title":"Bias isn''t fixed by size","body":"Sampling variability shrinks as $n$ grows; bias doesn''t. A huge sample with undercoverage is precisely wrong."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c5ca1b878a2a71', 'les_558a3358283bc6', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pollsters weight responses and test question wording because nonresponse and wording have shifted real election and health-survey results."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e5ecb7ecfc93a', 'les_558a3358283bc6', 1, 'practice', 'multiple_choice', 1, 'A survey on internet use is conducted only online. What problem is most likely?', '{"choices":["Nonresponse","Undercoverage of people without internet access","Wording","None"],"answer":1}', '[]', 'People offline can''t be selected.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aac370708567ff', 'les_558a3358283bc6', 2, 'practice', 'multiple_choice', 2, 'Asked in person how often they wash their hands, people overstate it. This is…', '{"choices":["Undercoverage","Nonresponse","Response bias","Sampling variability"],"answer":2}', '[]', 'Socially desirable answers.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cca95f3323693b', 'les_558a3358283bc6', 3, 'practice', 'multiple_choice', 2, 'Only 20% of mailed surveys about a new tax are returned, mostly from people angry about it. The likely effect is…', '{"choices":["Overestimating opposition to the tax","Underestimating opposition","No effect","Undercoverage"],"answer":0}', '[]', 'Nonresponse bias in the direction of the angry responders.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9cef302ed7d678', 'les_558a3358283bc6', 4, 'review', 'multiple_choice', 3, 'Which reduces sampling variability but not bias?', '{"choices":["Better question wording","Increasing the sample size","Following up nonresponders","Including people without phones"],"answer":1}', '[]', 'Larger $n$ makes estimates more consistent, not more correct.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_558a3358283bc6', (SELECT id FROM concepts WHERE slug = 'sampling'));

-- Lesson: sampling-dist-diff-means
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_db7b22a6b016f5', 'sampling-dist-diff-means', 'Sampling distributions for differences in sample means', 'Describe the sampling distribution of x̄₁ − x̄₂ for independent samples, compute its standard deviation by adding variances, and find probabilities.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aa31f597b96f55', 'les_db7b22a6b016f5', 1, 'State the mean μ₁ − μ₂ of x̄₁ − x̄₂.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4dbd26bd4050b', 'les_db7b22a6b016f5', 2, 'Compute its standard deviation √(σ₁²/n₁ + σ₂²/n₂).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4a0f675559d0e8', 'les_db7b22a6b016f5', 3, 'Check normality for both groups and compute probabilities.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aa31f597b96f55', 'les_db7b22a6b016f5', 'learn', 1, 'definition', '{"term":"The distribution","body":"For independent random samples: mean $\\mu_1 - \\mu_2$; standard deviation $\\sqrt{\\frac{\\sigma_1^2}{n_1} + \\frac{\\sigma_2^2}{n_2}}$; normal if both populations are normal, approximately normal if both $n_1$ and $n_2$ are at least 30."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4dbd26bd4050b', 'les_db7b22a6b016f5', 'learn', 2, 'worked_example', '{"title":"Brand A batteries: $\\mu = 40$ h, $\\sigma = 6$; brand B: $\\mu = 38$ h, $\\sigma = 8$. Samples of 36 A and 64 B.","steps":[{"latex":"\\text{mean} = 2","explanation":""},{"latex":"\\text{SD} = \\sqrt{\\tfrac{36}{36} + \\tfrac{64}{64}} = \\sqrt{2} \\approx 1.41","explanation":""},{"latex":"P(\\bar{x}_A - \\bar{x}_B < 0) = P(Z < -1.41) \\approx 0.079","explanation":"About an 8% chance the B sample averages longer."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4a0f675559d0e8', 'les_db7b22a6b016f5', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Before running a study, researchers use this distribution to see how likely they are to detect a real difference in means with the sample sizes they can afford."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aa31f597b96f55', 'les_db7b22a6b016f5', 1, 'practice', 'numeric', 1, '$\mu_1 = 75$, $\mu_2 = 70$. Find the mean of $\bar{x}_1 - \bar{x}_2$.', '{"answer":5}', '[]', '$75 - 70 = 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4dbd26bd4050b', 'les_db7b22a6b016f5', 2, 'practice', 'numeric', 2, '$\sigma_1 = 10$, $n_1 = 25$, $\sigma_2 = 12$, $n_2 = 36$. Find the SD of $\bar{x}_1 - \bar{x}_2$ to two decimal places.', '{"answer":2.83,"tolerance":0.01}', '[]', '$\sqrt{4 + 4} = \sqrt{8} \approx 2.83$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4a0f675559d0e8', 'les_db7b22a6b016f5', 3, 'practice', 'multiple_choice', 2, 'Both populations are skewed, with $n_1 = 50$ and $n_2 = 12$. Is $\bar{x}_1 - \bar{x}_2$ approximately normal?', '{"choices":["Yes","Not necessarily: n₂ is small and that population is skewed","Only if μ₁ = μ₂","Always"],"answer":1}', '[]', 'Both samples need to be large (or their populations normal).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_768a63e9fa5a42', 'les_db7b22a6b016f5', 4, 'review', 'multiple_choice', 3, 'Why is the SD of the difference larger than either group''s SD of $\bar{x}$?', '{"choices":["Rounding","Variability from both independent samples adds","Because μ₁ > μ₂","It isn''t"],"answer":1}', '[]', 'Variances add.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_db7b22a6b016f5', (SELECT id FROM concepts WHERE slug = 'sampling-distributions'));

-- Lesson: sampling-dist-diff-proportions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_84462cb4135895', 'sampling-dist-diff-proportions', 'Sampling distributions for differences in sample proportions', 'Describe the sampling distribution of p̂₁ − p̂₂ from independent samples: its center, its standard deviation from adding variances, and when it is approximately normal.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dd8138dad6eeb1', 'les_84462cb4135895', 1, 'State the mean of p̂₁ − p̂₂.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1d2b31b44e95b4', 'les_84462cb4135895', 2, 'Compute its standard deviation √(p₁(1 − p₁)/n₁ + p₂(1 − p₂)/n₂).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1f7fc89ecabeda', 'les_84462cb4135895', 3, 'Check the Large Counts condition in both groups and find probabilities.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd8138dad6eeb1', 'les_84462cb4135895', 'learn', 1, 'definition', '{"term":"The distribution","body":"For independent random samples: mean $p_1 - p_2$; standard deviation $\\sqrt{\\frac{p_1(1 - p_1)}{n_1} + \\frac{p_2(1 - p_2)}{n_2}}$ (variances add); approximately normal if $n_1p_1$, $n_1(1 - p_1)$, $n_2p_2$, $n_2(1 - p_2)$ are all at least 10."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1d2b31b44e95b4', 'les_84462cb4135895', 'learn', 2, 'worked_example', '{"title":"60% of city A residents and 50% of city B residents support a plan. Random samples: 100 from A, 150 from B.","steps":[{"latex":"\\text{mean} = 0.6 - 0.5 = 0.1","explanation":""},{"latex":"\\text{SD} = \\sqrt{\\tfrac{0.24}{100} + \\tfrac{0.25}{150}} = \\sqrt{0.004067} \\approx 0.0638","explanation":""},{"latex":"P(\\hat{p}_A - \\hat{p}_B < 0) = P\\left(Z < \\tfrac{-0.1}{0.0638}\\right) = P(Z < -1.57) \\approx 0.058","explanation":"About a 6% chance the samples show B ahead."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1f7fc89ecabeda', 'les_84462cb4135895', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"Comparing two polls, two treatment groups or two web designs always involves a difference of proportions and its variability."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dd8138dad6eeb1', 'les_84462cb4135895', 1, 'practice', 'numeric', 1, '$p_1 = 0.7$, $p_2 = 0.55$. Find the mean of $\hat{p}_1 - \hat{p}_2$.', '{"answer":0.15,"tolerance":0.001}', '[]', '$0.7 - 0.55 = 0.15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1d2b31b44e95b4', 'les_84462cb4135895', 2, 'practice', 'numeric', 2, '$p_1 = p_2 = 0.5$, $n_1 = n_2 = 100$. Find the SD of $\hat{p}_1 - \hat{p}_2$ to four decimal places.', '{"answer":0.0707,"tolerance":0.0002}', '[]', '$\sqrt{0.0025 + 0.0025} = \sqrt{0.005} \approx 0.0707$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1f7fc89ecabeda', 'les_84462cb4135895', 3, 'practice', 'multiple_choice', 2, 'Why do the variances add for a difference?', '{"choices":["Because p₁ > p₂","Because the samples are independent, and both sources of variability remain","They don''t","Because n is large"],"answer":1}', '[]', 'The variance of a difference of independent variables is the sum of variances.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9bfd51e32572a8', 'les_84462cb4135895', 4, 'review', 'multiple_choice', 3, '$n_1 = 40$, $p_1 = 0.1$; $n_2 = 200$, $p_2 = 0.3$. Is the normal model reasonable?', '{"choices":["Yes","No: n₁p₁ = 4 < 10","No: n₂p₂ < 10","Only if p₁ = p₂"],"answer":1}', '[]', 'One group fails the Large Counts condition.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_84462cb4135895', (SELECT id FROM concepts WHERE slug = 'sampling-distributions'));

-- Lesson: sampling-distribution-means
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ea6db7d2bdd64d', 'sampling-distribution-means', 'Sampling distributions for sample means', 'Describe the sampling distribution of x̄ (mean μ, standard deviation σ/√n, shape normal or approximately normal by the CLT) and use it to find probabilities about sample means.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bb08facae13d38', 'les_ea6db7d2bdd64d', 1, 'State the mean and standard deviation of x̄ and the 10% condition.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fa514431365bb2', 'les_ea6db7d2bdd64d', 2, 'Decide whether x̄ is normal, approximately normal or neither.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_537d445aea6dbb', 'les_ea6db7d2bdd64d', 3, 'Compute probabilities about x̄ with z-scores.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bb08facae13d38', 'les_ea6db7d2bdd64d', 'learn', 1, 'definition', '{"term":"Sampling distribution of x̄","body":"Mean $\\mu_{\\bar{x}} = \\mu$; standard deviation $\\sigma_{\\bar{x}} = \\frac{\\sigma}{\\sqrt{n}}$ when $n \\le 10\\%$ of the population. Shape: normal if the population is normal; approximately normal if $n \\ge 30$ (CLT)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fa514431365bb2', 'les_ea6db7d2bdd64d', 'learn', 2, 'worked_example', '{"title":"Adult men''s heights are normal with $\\mu = 170$ cm and $\\sigma = 10$ cm. Find $P(\\bar{x} > 173)$ for 25 men.","steps":[{"latex":"\\sigma_{\\bar{x}} = \\frac{10}{5} = 2","explanation":""},{"latex":"z = \\frac{173 - 170}{2} = 1.5","explanation":""},{"latex":"P(Z > 1.5) \\approx 0.067","explanation":"Compare: one man taller than 173 cm has probability about 0.38."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_537d445aea6dbb', 'les_ea6db7d2bdd64d', 'learn', 3, 'callout', '{"tone":"tip","title":"Individuals vs averages","body":"Averages vary less than individuals. A single value 3 cm above average is common; a sample mean 3 cm above average is unusual."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_049402317cfa6c', 'les_ea6db7d2bdd64d', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Elevator capacity limits are set using the distribution of the mean weight of a group of riders."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bb08facae13d38', 'les_ea6db7d2bdd64d', 1, 'practice', 'numeric', 1, '$\sigma = 20$, $n = 100$. Find $\sigma_{\bar{x}}$.', '{"answer":2}', '[]', '$\frac{20}{10} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fa514431365bb2', 'les_ea6db7d2bdd64d', 2, 'practice', 'numeric', 2, '$\mu = 50$, $\sigma = 8$, $n = 16$, population normal. Find $P(\bar{x} < 47)$ to three decimal places.', '{"answer":0.067,"tolerance":0.002}', '["$\\sigma_{\\bar{x}} = 2$."]', '$z = -1.5$, $P \approx 0.067$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_537d445aea6dbb', 'les_ea6db7d2bdd64d', 3, 'practice', 'multiple_choice', 2, 'A population is skewed and $n = 10$. The sampling distribution of $\bar{x}$ is…', '{"choices":["normal","approximately normal","not necessarily normal","uniform"],"answer":2}', '[]', 'Neither the population is normal nor $n \ge 30$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_049402317cfa6c', 'les_ea6db7d2bdd64d', 4, 'review', 'multiple_choice', 3, 'To cut $\sigma_{\bar{x}}$ to one third, multiply the sample size by…', '{"choices":["3","6","9","1/3"],"answer":2}', '[]', '$\sqrt{9} = 3$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ea6db7d2bdd64d', (SELECT id FROM concepts WHERE slug = 'sampling-distributions'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ea6db7d2bdd64d', (SELECT id FROM formulas WHERE slug = 'z-score'), 1);

-- Lesson: slope-confidence-interval
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_af9f474808e847', 'slope-confidence-interval', 'Confidence intervals for the slope of a regression model', 'Construct and interpret a t interval for the true slope β of a population regression line, using b ± t*·SE_b with n − 2 degrees of freedom, and check the LINER conditions.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_17e9748867e15d', 'les_af9f474808e847', 1, 'Distinguish the sample slope b from the population slope β.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b171f28ad9b1a9', 'les_af9f474808e847', 2, 'Check the conditions: Linear, Independent, Normal, Equal SD, Random.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_429d65e681e401', 'les_af9f474808e847', 3, 'Compute and interpret b ± t*·SE_b with df = n − 2.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_17e9748867e15d', 'les_af9f474808e847', 'learn', 1, 'definition', '{"term":"Model","body":"The population regression line $\\mu_y = \\alpha + \\beta x$ describes the mean response at each $x$. The sample slope $b$ estimates $\\beta$, and varies from sample to sample with standard error $SE_b$ (from computer output)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b171f28ad9b1a9', 'les_af9f474808e847', 'learn', 2, 'definition', '{"term":"Conditions (LINER)","body":"Linear: the residual plot shows no pattern. Independent: observations are independent (10% condition when sampling). Normal: responses vary normally about the line (check a histogram of residuals). Equal SD: the residual plot shows no fan shape. Random: random sample or random assignment."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_429d65e681e401', 'les_af9f474808e847', 'learn', 3, 'worked_example', '{"title":"A random sample of 12 used cars: price vs age, $b = 2.4$ (thousand dollars lost per year), $SE_b = 0.8$. Build a 95% interval.","steps":[{"latex":"df = 10,\\ t^* = 2.228","explanation":""},{"latex":"2.4 \\pm 2.228(0.8) = 2.4 \\pm 1.78","explanation":""},{"latex":"(0.62,\\ 4.18)","explanation":"We are 95% confident the true mean price drop is between about 620 and 4,180 dollars per year of age."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a13bb564d2f9b', 'les_af9f474808e847', 'learn', 4, 'callout', '{"tone":"tip","title":"Reading computer output","body":"Regression output lists the slope in the row for the explanatory variable: ''Coef'' is $b$ and ''SE Coef'' is $SE_b$. The value labeled S is the residual standard deviation, not $SE_b$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_228a08c76dad6b', 'les_af9f474808e847', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Economists report intervals for slopes such as the effect of an extra year of education on earnings."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_17e9748867e15d', 'les_af9f474808e847', 1, 'practice', 'numeric', 1, 'How many degrees of freedom for slope inference with $n = 20$?', '{"answer":18}', '[]', '$n - 2 = 18$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b171f28ad9b1a9', 'les_af9f474808e847', 2, 'practice', 'numeric', 2, '$b = 1.5$, $SE_b = 0.5$, $t^* = 2.145$. Find the upper bound of the interval to three decimal places.', '{"answer":2.573,"tolerance":0.001}', '[]', '$1.5 + 2.145(0.5) = 2.5725 \approx 2.573$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_429d65e681e401', 'les_af9f474808e847', 3, 'practice', 'multiple_choice', 2, 'A 95% interval for $\beta$ is (−0.3, 1.2). What does this suggest?', '{"choices":["Convincing evidence of a positive slope","No convincing evidence of a linear relationship; 0 is plausible","The slope is 0","The interval is wrong"],"answer":1}', '[]', '0 is inside the interval.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a13bb564d2f9b', 'les_af9f474808e847', 4, 'review', 'multiple_choice', 3, 'A residual plot shows a fan shape. Which condition is violated?', '{"choices":["Linear","Independent","Normal","Equal SD"],"answer":3}', '[]', 'The spread of residuals changes with $x$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_af9f474808e847', (SELECT id FROM concepts WHERE slug = 'regression'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_af9f474808e847', (SELECT id FROM concepts WHERE slug = 'confidence-intervals'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_af9f474808e847', (SELECT id FROM formulas WHERE slug = 'least-squares-line'), 1);

-- Lesson: slope-t-test
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b5a8869038ca95', 'slope-t-test', 'Carrying out a test for the slope of a regression model', 'Test whether there is a linear relationship between two quantitative variables in a population with t = b / SE_b and n − 2 degrees of freedom.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_85e2872a555241', 'les_b5a8869038ca95', 1, 'State hypotheses H₀: β = 0 and an appropriate alternative.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_da42ad62399e1b', 'les_b5a8869038ca95', 2, 'Compute t = (b − 0)/SE_b and its P-value, or read them from computer output.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d3455c8628b8af', 'les_b5a8869038ca95', 3, 'Conclude in context about the linear relationship.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_85e2872a555241', 'les_b5a8869038ca95', 'learn', 1, 'definition', '{"term":"The test","body":"$H_0: \\beta = 0$ (no linear relationship). $t = \\frac{b - 0}{SE_b}$ with $df = n - 2$. Conditions are the same as for the interval (LINER)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_da42ad62399e1b', 'les_b5a8869038ca95', 'learn', 2, 'worked_example', '{"title":"For the 12 used cars ($b = 2.4$, $SE_b = 0.8$), is there a linear relationship between age and price drop? $\\alpha = 0.05$.","steps":[{"latex":"H_0: \\beta = 0,\\ H_a: \\beta \\ne 0","explanation":""},{"latex":"t = \\frac{2.4}{0.8} = 3.0,\\ df = 10","explanation":""},{"latex":"\\text{P-value} = 2P(t_{10} \\ge 3.0) \\approx 0.013","explanation":""},{"latex":"\\text{reject } H_0","explanation":"Convincing evidence of a linear relationship between age and price for cars like these. The 95% interval (0.62, 4.18) agrees: it excludes 0."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d3455c8628b8af', 'les_b5a8869038ca95', 'learn', 3, 'callout', '{"tone":"tip","title":"Computer output","body":"Most software reports $t$ and a two-sided P-value for $H_0: \\beta = 0$ in the slope row. For a one-sided alternative, halve the P-value if $b$ is in the direction of $H_a$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c9f547a6ae15b2', 'les_b5a8869038ca95', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Scientists test whether a dose is linearly related to a response before using the slope to make predictions."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_85e2872a555241', 'les_b5a8869038ca95', 1, 'practice', 'numeric', 1, '$b = -1.2$, $SE_b = 0.4$. Find $t$.', '{"answer":-3}', '[]', '$\frac{-1.2}{0.4} = -3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_da42ad62399e1b', 'les_b5a8869038ca95', 2, 'practice', 'multiple_choice', 2, 'Output shows a slope P-value of 0.25 for $H_a: \beta \ne 0$. The conclusion is…', '{"choices":["Reject H₀","No convincing evidence of a linear relationship","β = 0","r = 0.25"],"answer":1}', '[]', 'Large P-value.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d3455c8628b8af', 'les_b5a8869038ca95', 3, 'practice', 'multiple_choice', 2, 'Output gives a two-sided P-value of 0.04, and $b > 0$. What is the P-value for $H_a: \beta > 0$?', '{"choices":["0.02","0.04","0.08","0.96"],"answer":0}', '[]', 'Half of 0.04, since $b$ is positive.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c9f547a6ae15b2', 'les_b5a8869038ca95', 4, 'review', 'numeric', 3, 'With $n = 16$, $t = 2.5$ for $H_a: \beta \ne 0$. How many degrees of freedom does the test use?', '{"answer":14}', '[]', '$16 - 2 = 14$ (the P-value is about 0.025).');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b5a8869038ca95', (SELECT id FROM concepts WHERE slug = 'regression'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b5a8869038ca95', (SELECT id FROM concepts WHERE slug = 'significance-tests'));

-- Lesson: t-distributions
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7e296194d2c8f5', 't-distributions', 'Introducing statistics: should I worry about error?', 'Understand standard error and why estimating σ with s calls for t distributions; read t* critical values for different degrees of freedom.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cc57e137406a50', 'les_7e296194d2c8f5', 1, 'Distinguish standard deviation, standard error and margin of error.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_28adcea61b4cad', 'les_7e296194d2c8f5', 2, 'Describe how t distributions differ from the standard normal.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e2dd255f52eebf', 'les_7e296194d2c8f5', 3, 'Find t* for a confidence level and degrees of freedom.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc57e137406a50', 'les_7e296194d2c8f5', 'learn', 1, 'definition', '{"term":"Standard error","body":"When we estimate the standard deviation of a statistic from data, we call it a standard error. For $\\bar{x}$: $SE = \\frac{s}{\\sqrt{n}}$. It describes how far $\\bar{x}$ typically is from $\\mu$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_28adcea61b4cad', 'les_7e296194d2c8f5', 'learn', 2, 'definition', '{"term":"t distributions","body":"$t = \\frac{\\bar{x} - \\mu}{s/\\sqrt{n}}$ follows a $t$ distribution with $n - 1$ degrees of freedom. It''s symmetric about 0 with heavier tails than the normal, because $s$ varies from sample to sample. As df grows, $t$ approaches $z$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e2dd255f52eebf', 'les_7e296194d2c8f5', 'learn', 3, 'worked_example', '{"title":"95% critical values","steps":[{"latex":"df = 5: t^* = 2.571;\\ df = 10: 2.228;\\ df = 30: 2.042","explanation":""},{"latex":"z^* = 1.960","explanation":"The t values shrink toward z* as df grows."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aca00744555ab5', 'les_7e296194d2c8f5', 'learn', 4, 'callout', '{"tone":"tip","title":"Three kinds of ''error''","body":"Standard deviation: spread of the data. Standard error: estimated spread of a statistic. Margin of error: critical value × standard error, the half-width of an interval. None of them accounts for bias."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_130a7793d629e3', 'les_7e296194d2c8f5', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"William Gosset developed the t distribution at the Guinness brewery to make reliable decisions from small samples of barley and beer."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cc57e137406a50', 'les_7e296194d2c8f5', 1, 'practice', 'numeric', 1, '$s = 12$, $n = 9$. Find the standard error of $\bar{x}$.', '{"answer":4}', '[]', '$\frac{12}{3} = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_28adcea61b4cad', 'les_7e296194d2c8f5', 2, 'practice', 'multiple_choice', 1, 'How many degrees of freedom for a one-sample t procedure with $n = 20$?', '{"choices":["20","19","21","18"],"answer":1}', '[]', '$n - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e2dd255f52eebf', 'les_7e296194d2c8f5', 3, 'practice', 'multiple_choice', 2, 'Compared with the standard normal, a t distribution with 4 df has…', '{"choices":["lighter tails","heavier tails","a different center","no symmetry"],"answer":1}', '[]', 'More probability in the tails.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aca00744555ab5', 'les_7e296194d2c8f5', 4, 'review', 'multiple_choice', 3, 'Margin of error accounts for…', '{"choices":["sampling variability only","bias from nonresponse","wording bias","all errors"],"answer":0}', '[]', 'It reflects random sampling variability, not bias.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7e296194d2c8f5', (SELECT id FROM concepts WHERE slug = 'confidence-intervals'));

-- Lesson: t-test-mean
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_29148ed7bc4994', 't-test-mean', 'Carrying out a test for a population mean', 'Carry out a one-sample t test for μ: hypotheses, conditions, t = (x̄ − μ₀)/(s/√n) with n − 1 df, P-value and conclusion. Paired data use the same test on differences.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a44199f8b70dd8', 'les_29148ed7bc4994', 1, 'State hypotheses about μ and check the Random, 10% and Normal/Large Sample conditions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ba2d4b8cd8fef4', 'les_29148ed7bc4994', 2, 'Compute the t statistic and P-value with n − 1 degrees of freedom.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cc364e8787411c', 'les_29148ed7bc4994', 3, 'Apply the one-sample t test to paired differences.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a44199f8b70dd8', 'les_29148ed7bc4994', 'learn', 1, 'definition', '{"term":"The test statistic","body":"$t = \\frac{\\bar{x} - \\mu_0}{s/\\sqrt{n}}$, with $df = n - 1$. Find the P-value from a t table or technology."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba2d4b8cd8fef4', 'les_29148ed7bc4994', 'learn', 2, 'worked_example', '{"title":"A machine should fill bottles with 500 mL. A random sample of 25 bottles has $\\bar{x} = 497.8$ mL, $s = 5$ mL. Is the mean fill different from 500? $\\alpha = 0.05$.","steps":[{"latex":"H_0: \\mu = 500,\\ H_a: \\mu \\ne 500","explanation":""},{"latex":"\\text{Random; } n = 25 < 30 \\text{, so check the sample''s dot plot for strong skew or outliers}","explanation":"Assume none."},{"latex":"t = \\frac{497.8 - 500}{5/\\sqrt{25}} = -2.2,\\ df = 24","explanation":""},{"latex":"\\text{P-value} = 2P(t_{24} \\le -2.2) \\approx 0.038","explanation":""},{"latex":"0.038 < 0.05 \\Rightarrow \\text{reject } H_0","explanation":"Convincing evidence the machine''s mean fill differs from 500 mL."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc364e8787411c', 'les_29148ed7bc4994', 'learn', 3, 'definition', '{"term":"Paired t test","body":"For paired data, compute the differences and test $H_0: \\mu_{\\text{diff}} = 0$ with a one-sample t test on the differences."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_21fe8d0057866c', 'les_29148ed7bc4994', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Regulators test whether mean emissions exceed a limit; coaches test whether training changed mean sprint times (paired, before and after)."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a44199f8b70dd8', 'les_29148ed7bc4994', 1, 'practice', 'numeric', 1, '$\bar{x} = 52$, $\mu_0 = 50$, $s = 6$, $n = 36$. Find $t$.', '{"answer":2}', '[]', '$\frac{2}{6/6} = 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ba2d4b8cd8fef4', 'les_29148ed7bc4994', 2, 'practice', 'multiple_choice', 2, 'With $t = 2$ and $df = 35$, $H_a: \mu > 50$, the P-value is about…', '{"choices":["0.027","0.05","0.27","0.0027"],"answer":0}', '[]', '$P(t_{35} \ge 2) \approx 0.027$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cc364e8787411c', 'les_29148ed7bc4994', 3, 'practice', 'multiple_choice', 2, 'Ten students'' scores are measured before and after a course. The right test is…', '{"choices":["Two-sample t","One-sample t on the 10 differences","Two-proportion z","Chi-square"],"answer":1}', '[]', 'Paired data.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_21fe8d0057866c', 'les_29148ed7bc4994', 4, 'review', 'multiple_choice', 3, 'A t test with $n = 8$ is planned, and the data''s dot plot shows a strong outlier. What should you do?', '{"choices":["Proceed normally","Be cautious: the Normal condition is questionable, so the P-value may be unreliable","Use z instead","Double the sample"],"answer":1}', '[]', 'Small samples need roughly symmetric data without outliers.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_29148ed7bc4994', (SELECT id FROM concepts WHERE slug = 'significance-tests'));

-- Lesson: two-proportion-z-test
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4b48e61459f9bf', 'two-proportion-z-test', 'Testing for a difference in two population proportions', 'Carry out a two-sample z test for p₁ − p₂ using the pooled proportion, from hypotheses through conditions, P-value and a conclusion in context.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8f3d0967410a2c', 'les_4b48e61459f9bf', 1, 'State H₀: p₁ = p₂ and an appropriate alternative.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b0fedf22f2cf4e', 'les_4b48e61459f9bf', 2, 'Compute the pooled proportion and the z statistic.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9639a599702e41', 'les_4b48e61459f9bf', 3, 'Conclude in context, including scope of inference.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8f3d0967410a2c', 'les_4b48e61459f9bf', 'learn', 1, 'definition', '{"term":"The test","body":"$z = \\frac{\\hat{p}_1 - \\hat{p}_2}{\\sqrt{\\hat{p}_c(1 - \\hat{p}_c)\\left(\\frac{1}{n_1} + \\frac{1}{n_2}\\right)}}$ with $\\hat{p}_c = \\frac{x_1 + x_2}{n_1 + n_2}$. Large Counts: $n_1\\hat{p}_c$, $n_1(1 - \\hat{p}_c)$, $n_2\\hat{p}_c$, $n_2(1 - \\hat{p}_c)$ all at least 10."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0fedf22f2cf4e', 'les_4b48e61459f9bf', 'learn', 2, 'worked_example', '{"title":"Randomized experiment: 120 of 200 improved on a new drug, 90 of 200 on the standard. Does the new drug work better? $\\alpha = 0.05$.","steps":[{"latex":"H_0: p_N = p_S,\\ H_a: p_N > p_S","explanation":""},{"latex":"\\hat{p}_c = \\tfrac{210}{400} = 0.525","explanation":"Counts: 105 and 95 in each group, all ≥ 10."},{"latex":"SE = \\sqrt{0.525 \\cdot 0.475 \\cdot \\tfrac{2}{200}} \\approx 0.0499","explanation":""},{"latex":"z = \\frac{0.60 - 0.45}{0.0499} \\approx 3.00,\\ \\text{P-value} \\approx 0.0013","explanation":""},{"latex":"\\text{reject } H_0","explanation":"Convincing evidence the new drug causes a higher improvement rate for subjects like these."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9639a599702e41', 'les_4b48e61459f9bf', 'learn', 3, 'callout', '{"tone":"application","title":"Where this shows up","body":"A/B tests on websites run this test on conversion rates before a company switches designs."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8f3d0967410a2c', 'les_4b48e61459f9bf', 1, 'practice', 'numeric', 1, '$x_1 = 30$, $n_1 = 100$, $x_2 = 50$, $n_2 = 150$. Find $\hat{p}_c$.', '{"answer":0.32,"tolerance":0.001}', '[]', '$\frac{80}{250} = 0.32$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0fedf22f2cf4e', 'les_4b48e61459f9bf', 2, 'practice', 'multiple_choice', 2, 'Why use the pooled proportion in the test?', '{"choices":["It''s always more accurate","H₀ assumes p₁ = p₂, so we estimate the common value","It makes z larger","It''s required for intervals"],"answer":1}', '[]', 'The calculation assumes the null hypothesis.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9639a599702e41', 'les_4b48e61459f9bf', 3, 'practice', 'numeric', 2, 'A two-proportion test gives $z = 1.75$ for $H_a: p_1 \ne p_2$. Find the P-value to three decimal places.', '{"answer":0.08,"tolerance":0.002}', '["$P(Z > 1.75) \\approx 0.040$."]', 'Two-sided: $2(0.0401) \approx 0.080$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b72693e5bfaaf', 'les_4b48e61459f9bf', 4, 'review', 'multiple_choice', 3, 'Two random samples (not an experiment) show a significant difference in voting rates between age groups. The conclusion should say…', '{"choices":["Age causes the difference","The population proportions differ","There''s no difference","The samples are biased"],"answer":1}', '[]', 'Random samples allow generalization, not causation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4b48e61459f9bf', (SELECT id FROM concepts WHERE slug = 'significance-tests'));

-- Lesson: two-sample-t-test
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5177ac64e1bd61', 'two-sample-t-test', 'Carrying out a test for the difference of two population means', 'Carry out a two-sample t test of H₀: μ₁ = μ₂ with independent samples or groups, using technology degrees of freedom or the conservative choice, and conclude in context.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f33a8dff8bcc8e', 'les_5177ac64e1bd61', 1, 'Check conditions for both groups.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_83272119bccbba', 'les_5177ac64e1bd61', 2, 'Compute t = (x̄₁ − x̄₂)/√(s₁²/n₁ + s₂²/n₂) and its P-value.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fcd1b42df4de78', 'les_5177ac64e1bd61', 3, 'Distinguish two-sample from paired situations.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f33a8dff8bcc8e', 'les_5177ac64e1bd61', 'learn', 1, 'definition', '{"term":"The test","body":"$t = \\frac{(\\bar{x}_1 - \\bar{x}_2) - 0}{\\sqrt{s_1^2/n_1 + s_2^2/n_2}}$. Technology gives the degrees of freedom (often not a whole number); the conservative choice is the smaller of $n_1 - 1$ and $n_2 - 1$, which gives a slightly larger P-value."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_83272119bccbba', 'les_5177ac64e1bd61', 'learn', 2, 'worked_example', '{"title":"Plant growth (cm) with fertilizer: $n_1 = 20$, $\\bar{x}_1 = 15.2$, $s_1 = 3$. Without: $n_2 = 20$, $\\bar{x}_2 = 13.0$, $s_2 = 4$. Random assignment. $H_a: \\mu_1 \\ne \\mu_2$, $\\alpha = 0.05$.","steps":[{"latex":"SE = \\sqrt{\\tfrac{9}{20} + \\tfrac{16}{20}} = \\sqrt{1.25} \\approx 1.118","explanation":""},{"latex":"t = \\frac{2.2}{1.118} \\approx 1.97","explanation":""},{"latex":"df \\approx 35.2 \\text{ (technology)},\\ \\text{P-value} \\approx 0.057","explanation":"Conservative df = 19 gives about 0.064."},{"latex":"0.057 > 0.05 \\Rightarrow \\text{fail to reject } H_0","explanation":"Not convincing evidence that the fertilizer changes mean growth."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fcd1b42df4de78', 'les_5177ac64e1bd61', 'learn', 3, 'callout', '{"tone":"warning","title":"Failing to reject isn''t proving no effect","body":"A real effect of about 2 cm is still plausible; a larger experiment might detect it."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e25783c81c563', 'les_5177ac64e1bd61', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Clinical trials comparing mean blood pressure between treatment groups and education studies comparing two teaching methods use this test."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f33a8dff8bcc8e', 'les_5177ac64e1bd61', 1, 'practice', 'numeric', 2, '$\bar{x}_1 - \bar{x}_2 = 3$, $s_1 = 6$, $n_1 = 36$, $s_2 = 8$, $n_2 = 64$. Find $t$ to two decimal places.', '{"answer":2.12,"tolerance":0.01}', '["$SE = \\sqrt{1 + 1}$."]', '$\frac{3}{1.414} \approx 2.12$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_83272119bccbba', 'les_5177ac64e1bd61', 2, 'practice', 'multiple_choice', 2, 'The conservative degrees of freedom for $n_1 = 15$, $n_2 = 22$ are…', '{"choices":["14","21","35","37"],"answer":0}', '[]', 'The smaller of 14 and 21.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fcd1b42df4de78', 'les_5177ac64e1bd61', 3, 'practice', 'multiple_choice', 2, 'Ten twins are split so one twin of each pair gets diet A and the other diet B. Which test fits?', '{"choices":["Two-sample t","Paired t","Chi-square","z for proportions"],"answer":1}', '[]', 'Twins form natural pairs.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5e25783c81c563', 'les_5177ac64e1bd61', 4, 'review', 'multiple_choice', 3, 'A two-sample t test gives P-value 0.21. The best conclusion is…', '{"choices":["The means are equal","There''s no convincing evidence the means differ","The means differ by 21%","Reject H₀"],"answer":1}', '[]', 'Large P-value: not convincing evidence; never "accept" $H_0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5177ac64e1bd61', (SELECT id FROM concepts WHERE slug = 'significance-tests'));

