UPDATE lesson_blocks SET data = '{"title":"Behavior of $\\sin\\theta$ on $[0, 2\\pi]$","steps":[{"latex":"\\text{increasing on } \\left[0, \\tfrac{\\pi}{2}\\right] \\cup \\left[\\tfrac{3\\pi}{2}, 2\\pi\\right]","explanation":""},{"latex":"\\text{decreasing on } \\left[\\tfrac{\\pi}{2}, \\tfrac{3\\pi}{2}\\right]","explanation":""},{"latex":"\\text{concave down on } (0, \\pi)","explanation":""},{"latex":"\\text{concave up on } (\\pi, 2\\pi)","explanation":"Inflection points where the graph crosses the midline."}]}' WHERE id = 'blk_147528bc219be9' AND data = '{"title":"Behavior of $\\sin\\theta$ on $[0, 2\\pi]$","steps":[{"latex":"\\text{increasing on } \\left[0, \\tfrac{\\pi}{2}\\right] \\cup \\left[\\tfrac{3\\pi}{2}, 2\\pi\\right]","explanation":""},{"latex":"\\text{decreasing on } \\left[\\tfrac{\\pi}{2}, \\tfrac{3\\pi}{2}\\right]","explanation":""},{"latex":"\\text{concave down on } (0, \\pi),\\ \\text{up on } (\\pi, 2\\pi)","explanation":"Inflection points where the graph crosses the midline."}]}';
UPDATE lesson_blocks SET data = '{"title":"Solve $2x^2 - 5x - 3 = 0$","steps":[{"latex":"(2x + 1)(x - 3) = 0","explanation":"ac method: −6 = −6 · 1, and −6 + 1 = −5."},{"latex":"x = -\\tfrac{1}{2} \\text{ or } x = 3","explanation":""}]}' WHERE id = 'blk_02600154b5b7fc' AND data = '{"title":"Solve $2x^2 - 5x - 3 = 0","steps":[{"latex":"(2x + 1)(x - 3) = 0","explanation":"ac method: −6 = −6 · 1, and −6 + 1 = −5."},{"latex":"x = -\\tfrac{1}{2} \\text{ or } x = 3","explanation":""}]}';

-- Courses that now have published lessons are in development, not planned.
UPDATE courses SET status = 'in_development', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
   WHERE status = 'planned' AND id IN (
     SELECT u.course_id FROM chapter_lessons cl JOIN lessons l ON l.id = cl.lesson_id
     JOIN chapters ch ON ch.id = cl.chapter_id JOIN units u ON u.id = ch.unit_id WHERE l.status = 'published');
